package bst_test

import (
	"testing"

	"github.com/ai-verification/go-bst/internal/bst"
)

func TestInsertAndSearch(t *testing.T) {
	tree := bst.New()
	tree.Insert(5)
	tree.Insert(3)
	tree.Insert(7)
	if !tree.Search(3) {
		t.Fatal("expected to find 3")
	}
	if tree.Search(99) {
		t.Fatal("expected 99 not found")
	}
}

func TestInOrder(t *testing.T) {
	tree := bst.New()
	for _, v := range []int{5, 3, 7, 1, 4} {
		tree.Insert(v)
	}
	got := tree.InOrder()
	want := []int{1, 3, 4, 5, 7}
	if len(got) != len(want) {
		t.Fatalf("expected %v, got %v", want, got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("index %d: expected %d got %d", i, want[i], got[i])
		}
	}
}

func TestHeight(t *testing.T) {
	tree := bst.New()
	if tree.Height() != 0 {
		t.Fatalf("expected height 0 for empty tree, got %d", tree.Height())
	}
	tree.Insert(5)
	if tree.Height() != 1 {
		t.Fatalf("expected height 1 after one insert, got %d", tree.Height())
	}
	tree.Insert(3)
	tree.Insert(7)
	if tree.Height() != 2 {
		t.Fatalf("expected height 2 after balanced insert, got %d", tree.Height())
	}
	tree.Insert(1)
	if tree.Height() != 3 {
		t.Fatalf("expected height 3, got %d", tree.Height())
	}
}

func TestDuplicateInsert(t *testing.T) {
	tree := bst.New()
	tree.Insert(5)
	tree.Insert(5)
	got := tree.InOrder()
	if len(got) != 1 {
		t.Fatalf("expected 1 node after duplicate insert, got %d", len(got))
	}
}

func TestSearchEmpty(t *testing.T) {
	tree := bst.New()
	if tree.Search(1) {
		t.Fatal("expected false on empty tree")
	}
}
